import{localizeTree}from"./chunk-MTVD26RU.js";function mountProjectStats(panel,stats,funding,{language="ru"}={}){const side=document.createElement("div");side.className="membership-side-body project-summary";side.innerHTML=`
    <div class="project-counts"></div>
    <section class="project-pilot" aria-label="\u041F\u0438\u043B\u043E\u0442 \u0434\u043D\u044F">
      <span class="project-pilot-mark" aria-hidden="true"></span>
      <div class="project-pilot-copy"><small>\u041F\u0438\u043B\u043E\u0442 \u0434\u043D\u044F</small><span class="project-pilot-slot"></span>
        <div class="project-ratings"></div></div>
    </section>
    <button type="button" class="membership-chart" data-modal="online" aria-haspopup="dialog"><span class="eyebrow">\u041E\u043D\u043B\u0430\u0439\u043D \u043F\u043E \u0434\u0430\u0442\u0430\u043C <i aria-hidden="true">\u2197</i></span><span class="chart"></span></button>
    <section class="project-goal" aria-label="\u0421\u0431\u043E\u0440 \u0441\u0440\u0435\u0434\u0441\u0442\u0432">
      <div class="project-goal-heading"><small>\u0426\u0435\u043B\u044C \u0441\u0431\u043E\u0440\u0430</small><b class="project-percent"></b></div>
      <strong class="project-goal-title"></strong>
      <div class="project-amount"><b></b> <span></span></div>
      <progress max="100" aria-label="\u041F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0441\u0431\u043E\u0440\u0430"></progress>
      <div class="project-donations" hidden><small>\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0435 \u0434\u043E\u043D\u0430\u0442\u044B</small><div class="project-donor-list"></div></div>
    </section>`;localizeTree(side,language);const trophy=document.querySelector("#v2-ranking .head-icon svg");if(trophy)side.querySelector(".project-pilot-mark").append(trophy.cloneNode(true));for(const selector of[".support-cta",".qr-section"])side.append(funding.querySelector(selector).cloneNode(true));const previous=panel.querySelector(".membership-side-body");if(previous)previous.replaceWith(side);else panel.append(side);const observers=[];function watch(node,update){update();const observer2=new MutationObserver(update);observer2.observe(node,{subtree:true,childList:true,characterData:true,attributes:true});observers.push(observer2)}const metrics=stats.querySelector("#v2-metrics");watch(metrics,()=>{const items=Array.from(metrics.children,child=>child.cloneNode(true));const labels=language==="en"?["Drivers","Races","Online"]:["\u041F\u0438\u043B\u043E\u0442\u044B","\u0413\u043E\u043D\u043A\u0438","\u041E\u043D\u043B\u0430\u0439\u043D"];items.forEach((item,index)=>{const label=item.querySelector("span");if(!label||!labels[index])return;item.title=label.textContent;label.textContent=labels[index]});side.querySelector(".project-counts").replaceChildren(...items)});const history=stats.querySelector("#v2-chart");watch(history,()=>side.querySelector(".chart").replaceChildren(...Array.from(history.children,child=>child.cloneNode(true))));const nativePilot=stats.querySelector("#v2-day-driver");const pilotParent=nativePilot.parentNode,pilotNext=nativePilot.nextSibling;const pilotClass=nativePilot.className,pilotPopup=nativePilot.getAttribute("aria-haspopup");nativePilot.classList.add("project-pilot-name");nativePilot.setAttribute("aria-haspopup","dialog");side.querySelector(".project-pilot-slot").replaceWith(nativePilot);const donations=funding.querySelector("#v2-donations");watch(donations,()=>{const entries=Array.from(donations.querySelectorAll(".donation-row")).slice(0,3);side.querySelector(".project-donations").hidden=!entries.length;side.querySelector(".project-donor-list").replaceChildren(...entries.map(entry=>{const row=document.createElement("div");row.className="project-donor";const name=document.createElement("b");name.textContent=entry.querySelector("b")?.textContent.trim()||"\u0410\u043D\u043E\u043D\u0438\u043C";name.title=name.textContent;const amount=document.createElement("strong");amount.textContent=entry.querySelector("strong")?.textContent.trim()||"";row.append(name,amount);return row}))});const ratings=stats.querySelector("#v2-day-ratings");watch(ratings,()=>{const badges=Array.from(ratings.querySelectorAll(".rating-badge"),original=>{const badge=document.createElement("span");badge.className=original.className;badge.textContent=original.textContent.trim();return badge});side.querySelector(".project-ratings").replaceChildren(...badges)});const title=funding.querySelector("#v2-goal-name");const raised=funding.querySelector("#v2-fund-value");const total=funding.querySelector("#v2-fund-total");const percent=funding.querySelector("#v2-fund-percent");function renderGoal(){const fullTitle=title.textContent.trim();const name=side.querySelector(".project-goal-title");name.textContent=fullTitle.replace(/\s*\/\s*Support the Project!.*$/i,"")||"\u0426\u0435\u043B\u044C \u0443\u0442\u043E\u0447\u043D\u044F\u0435\u0442\u0441\u044F";name.title=fullTitle;side.querySelector(".project-amount b").textContent=raised.textContent;side.querySelector(".project-amount span").textContent=total.textContent;side.querySelector(".project-percent").textContent=percent.textContent;const bar=side.querySelector("progress");bar.hidden=!percent.textContent.trim();if(!bar.hidden)bar.value=Number.parseFloat(percent.textContent)}renderGoal();const observer=new MutationObserver(renderGoal);for(const node of[title,raised,total,percent])observer.observe(node,{subtree:true,childList:true,characterData:true});observers.push(observer);return()=>{observers.forEach(o=>o.disconnect());pilotParent.insertBefore(nativePilot,pilotNext);nativePilot.className=pilotClass;if(pilotPopup===null)nativePilot.removeAttribute("aria-haspopup");else nativePilot.setAttribute("aria-haspopup",pilotPopup);side.remove()}}export{mountProjectStats};
